      }
      let env = 0;
      if (s.incident) {
        env = envelope(s.incident, tRel);
        if (env === 0 && tRel > s.incident.start + s.incident.dur + s.incident.rel) s.incident = null;
      }
      const v = Math.max(0, rawValue(m, tRel, env));
