1	/* ============================================================
2	 * PulseWall · stream.js — 本地模拟流引擎（无后端、无依赖）
3	 * 职责：指标定义、确定性种子历史（首屏即满数据）、1Hz 推进、
4	 *       滞回状态机（防闪烁）、事件生成、异常注入。
5	 * 全局命名空间：window.PulseStream
6	 * ============================================================ */
7	(function () {
8	  'use strict';
9	
10	  /* ---------- 确定性 PRNG（mulberry32）+ 高斯噪声 ---------- */
11	  function mulberry32(seed) {
12	    let a = seed >>> 0;
13	    return function () {
14	      a |= 0; a = (a + 0x6D2B79F5) | 0;
15	      let t = Math.imul(a ^ (a >>> 15), 1 | a);
16	      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
17	      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
18	    };
19	  }
20	  const rand = mulberry32(20260917);
21	  let spare = null;
22	  function gauss() {
23	    if (spare !== null) { const s = spare; spare = null; return s; }
24	    let u = 0, v = 0;
25	    while (u === 0) u = rand();
26	    while (v === 0) v = rand();
27	    const m = Math.sqrt(-2 * Math.log(u));
28	    spare = m * Math.sin(2 * Math.PI * v);
29	    return m * Math.cos(2 * Math.PI * v);
30	  }
31	
32	  /* ---------- 指标定义（24 项 · 4 域 · 位置即数组序，恒定不重排） ---------- */
33	  // dir=+1 越高越坏；dir=-1 越低越坏
34	  const METRICS = [
35	    // 接入网关 edge
36	    { id: 'http.rps',          name: '请求速率',   dom: 'edge', unit: 'req/s', base: 12400, dir: -1 },
37	    { id: 'http.p99',          name: '入口 P99',   dom: 'edge', unit: 'ms',    base: 118,   dir: +1 },
38	    { id: 'http.err',          name: '错误率',     dom: 'edge', unit: '%',     base: 0.42,  dir: +1 },
39	    { id: 'edge.cache',        name: '边缘缓存命中', dom: 'edge', unit: '%',   base: 92.5,  dir: -1 },
40	    { id: 'edge.conn',         name: '活动连接',   dom: 'edge', unit: '',      base: 4560,  dir: +1 },
41	    { id: 'edge.block',        name: '拦截速率',   dom: 'edge', unit: '/s',    base: 31,    dir: +1 },
42	    // 服务层 svc
43	    { id: 'svc.orders',        name: '订单 QPS',   dom: 'svc',  unit: '/s',    base: 852,   dir: -1 },
44	    { id: 'svc.pay.lat',       name: '支付延迟',   dom: 'svc',  unit: 'ms',    base: 182,   dir: +1 },
45	    { id: 'svc.cart.lat',      name: '购物车延迟', dom: 'svc',  unit: 'ms',    base: 61,    dir: +1 },
46	    { id: 'svc.search',        name: '搜索 QPS',   dom: 'svc',  unit: '/s',    base: 2380,  dir: -1 },
47	    { id: 'svc.queue',         name: '队列积压',   dom: 'svc',  unit: '条',    base: 128,   dir: +1 },
48	    { id: 'svc.retry',         name: '重试率',     dom: 'svc',  unit: '%',     base: 1.18,  dir: +1 },
49	    // 数据层 data
50	    { id: 'db.qps',            name: '查询 QPS',   dom: 'data', unit: '/s',    base: 5240,  dir: +1 },
51	    { id: 'db.lag',            name: '复制延迟',   dom: 'data', unit: 's',     base: 0.82,  dir: +1 },
52	    { id: 'db.slow',           name: '慢查询',     dom: 'data', unit: '/min',  base: 13.6,  dir: +1 },
53	    { id: 'cache.hit',         name: '缓存命中率', dom: 'data', unit: '%',     base: 88.4,  dir: -1 },
54	    { id: 'mq.lag',            name: '消息积压',   dom: 'data', unit: '万',    base: 2.35,  dir: +1 },
55	    { id: 'es.p95',            name: '检索 P95',   dom: 'data', unit: 'ms',    base: 216,   dir: +1 },
56	    // 资源层 infra
57	    { id: 'infra.cpu',         name: 'CPU 使用率', dom: 'infra', unit: '%',    base: 44.6,  dir: +1 },
58	    { id: 'infra.mem',         name: '内存使用率', dom: 'infra', unit: '%',    base: 61.8,  dir: +1 },
59	    { id: 'infra.iowait',      name: 'IO 等待',    dom: 'infra', unit: '%',    base: 5.8,   dir: +1 },
60	    { id: 'infra.net.out',     name: '出带宽',     dom: 'infra', unit: 'Gbps', base: 4.24,  dir: +1 },
61	    { id: 'infra.pod.restart', name: 'Pod 重启',   dom: 'infra', unit: '/h',   base: 0.52,  dir: +1 },
62	    { id: 'infra.pod.pend',    name: '待调度 Pod', dom: 'infra', unit: '个',   base: 3.1,   dir: +1 },
63	  ];
64	
65	  const DOM_LABELS = { edge: '接入网关', svc: '服务层', data: '数据层', infra: '资源层' };
66	  const DOM_ORDER = ['edge', 'svc', 'data', 'infra'];
67	
68	  const WINDOW = 90;          // 每指标 90 个采样点（≈90s）
69	  const WARN_K = 0.25;        // 警告阈值距离系数
70	  const CRIT_K = 0.45;        // 严重阈值距离系数
71	
72	  function thresholdsOf(m) {
73	    const wd = m.base * WARN_K, cd = m.base * CRIT_K;
74	    return m.dir > 0
75	      ? { warn: m.base + wd, crit: m.base + cd, wd: wd, cd: cd }
76	      : { warn: m.base - wd, crit: m.base - cd, wd: wd, cd: cd };
77	  }
78	
79	  /* ---------- 引擎状态 ---------- */
80	  const state = {};   // id -> { m, th, samples:[{t,v}], status, sinceT, okTicks, incident }
81	  let t0 = 0;
82	  let lastTickAt = 0;
83	  let running = true;
84	  let transitions = 0;
85	  const events = [];  // 新事件 unshift，cap 200
86	
87	  function noiseSigma(m) { return m.base * 0.022; }
88	
89	  function rawValue(m, tRel, envAmp) {
90	    // 均值回归随机游走 + 异常包络
91	    const s = state[m.id];
92	    const prev = s.samples.length ? s.samples[s.samples.length - 1].v : m.base;
93	    let v = prev + (m.base - prev) * 0.08 + gauss() * noiseSigma(m);
94	    if (envAmp) v += envAmp;
95	    return v;
96	  }
97	
98	  /* 异常包络形状：attack-hold-release */
99	  function envelope(inc, tRel) {
100	    if (!inc) return 0;
101	    const dt = tRel - inc.start;
102	    if (dt < 0 || dt > inc.dur + inc.rel) return 0;
103	    const a = Math.min(1, dt / inc.atk);
104	    let r = 1;
105	    if (dt > inc.dur) r = Math.max(0, 1 - (dt - inc.dur) / inc.rel);
106	    return inc.amp * a * r;
107	  }
108	
109	  function makeIncident(m, type, tStart) {
110	    const th = state[m.id].th;
111	    const overCrit = (th.crit - m.base) * 1.25; // 方向由 (crit-base) 符号自带（dir=-1 时为负）
112	    if (type === 'spike') {
113	      return { type: 'spike', start: tStart, dur: 6 + rand() * 4, atk: 1.5, rel: 4, amp: overCrit };
114	    }
115	    return { type: 'drift', start: tStart, dur: 24 + rand() * 10, atk: 6, rel: 4, amp: overCrit };
116	  }
117	
118	  /* ---------- 状态机（滞回 + 最短驻留 → 无闪烁） ---------- */
119	  function classify(m, v) {
120	    const th = state[m.id].th;
121	    const dir = m.dir > 0 ? 1 : -1;
122	    const s = (v - m.base) * dir;
123	    const margin = m.base * 0.02;
124	    const sCrit = (th.crit - m.base) * dir;
125	    const sWarn = (th.warn - m.base) * dir;
126	    if (s >= sCrit + margin) return 'crit';
127	    if (s >= sWarn + margin * 0.5) return 'warn';
128	    return 'ok';
129	  }
130	
131	  function advance(m, v, now) {
132	    const s = state[m.id];
133	    const proposed = classify(m, v);
134	    const dwell = now - s.sinceT;
135	    if (proposed === s.status) { s.okTicks = 0; return; }
136	    if (proposed === 'crit') { setStatus(m, v, now, 'crit'); return; }        // 升级立即
137	    if (proposed === 'warn') { if (dwell >= 3000) setStatus(m, v, now, 'warn'); return; }
138	    if (proposed === 'ok') {
139	      s.okTicks++;
140	      if (s.okTicks >= 3 && dwell >= 5000) setStatus(m, v, now, 'ok');        // 恢复需连续 3 拍确认
141	    }
142	  }
143	
144	  function setStatus(m, v, now, st) {
145	    const s = state[m.id];
146	    const from = s.status;
147	    s.status = st;
148	    s.sinceT = now;
149	    s.okTicks = 0;
150	    if (st === 'ok') s.injectFlag = false;
151	    if (from === st) return;
152	    transitions++;
153	    if (from !== null) {
154	      const kind = st === 'ok' ? 'ok' : st;
155	      events.unshift({
156	        t: now, id: m.id, name: m.name, unit: m.unit,
157	        kind: s.injectFlag && st !== 'ok' ? 'inject' : kind,
158	        from: from, to: st, v: v,
159	        msg: st === 'ok'
160	          ? '恢复正常 ' + fmt(m, v) + m.unit
161	          : (st === 'crit' ? '升至严重 ' : '进入警告 ') + fmt(m, v) + m.unit
162	      });
163	      if (events.length > 200) events.pop();
164	    }
165	  }
166	
167	  /* ---------- 数值格式化 ---------- */
168	  function fmt(m, v) {
169	    if (m.unit === '%') return v.toFixed(1);
170	    if (Math.abs(m.base) >= 1000) return Math.round(v).toLocaleString('en-US');
171	    if (Math.abs(m.base) >= 100) return v.toFixed(0);
172	    if (Math.abs(m.base) >= 10) return v.toFixed(1);
173	    return v.toFixed(2);
174	  }
175	
176	  /* ---------- 种子历史（首屏即满数据，无加载态） ---------- */
177	  // 预置异常：svc.queue 漂移中（t0-35s 起，60s 时长）→ 加载即为 warn，约 15s 后升 crit
178	  const SEEDED_INCIDENTS = [
179	    { id: 'svc.queue', type: 'drift', start: 35, dur: 60, atk: 6, rel: 4 },
180	  ];
181	  // 预置历史事件（与包络大体吻合，构成可追溯的既有证据链）
182	  const SEEDED_EVENTS = [
183	    { ago: 47000, id: 'infra.net.out', kind: 'ok',   from: 'warn', to: 'ok' },
184	    { ago: 62000, id: 'infra.net.out', kind: 'warn', from: 'ok',   to: 'warn' },
185	    { ago: 74000, id: 'infra.cpu',     kind: 'ok',   from: 'crit', to: 'ok' },
186	    { ago: 82000, id: 'infra.cpu',     kind: 'crit', from: 'warn', to: 'crit' },
187	    { ago: 86000, id: 'infra.cpu',     kind: 'warn', from: 'ok',   to: 'warn' },
188	  ];
189	
190	  function seed() {
191	    t0 = Date.now();
192	    const incMap = {};
193	    SEEDED_INCIDENTS.forEach(function (si) {
194	      const m = METRICS.find(function (x) { return x.id === si.id; });
195	      incMap[si.id] = {
196	        type: si.type, start: si.start, dur: si.dur, atk: si.atk, rel: si.rel,
197	        amp: (state[si.id].th.crit - m.base) * 1.25
198	      };
199	    });
200	    METRICS.forEach(function (m) {
201	      const s = state[m.id];
202	      s.samples = [];
203	      for (let i = WINDOW - 1; i >= 0; i--) {
204	        const t = t0 - i * 1000;
205	        const inc = incMap[m.id];
206	        // inc.start 为“距 now 的秒数”：采样 i 秒前位于异常开始后 (start - i) 秒
207	        const env = inc ? envelope(inc, inc.start - i) : 0;
208	        const prev = s.samples.length ? s.samples[s.samples.length - 1].v : m.base;
209	        const v = prev + (m.base - prev) * 0.08 + gauss() * noiseSigma(m) + env;
210	        s.samples.push({ t: t, v: v });
211	      }
212	      const last = s.samples[s.samples.length - 1].v;
213	      const raw = classify(m, last);
214	      s.status = raw === 'warn' || raw === 'crit' ? raw : 'ok';
215	      s.sinceT = t0 - 32000; // 预置异常已持续 ~32s
216	      s.okTicks = 0;
217	      if (raw !== 'ok') s.sinceT = t0 - (SEEDED_INCIDENTS[0].id === m.id ? 32 : 20) * 1000;
218	      s.incident = incMap[m.id] || null;
219	    });
220	    SEEDED_EVENTS.forEach(function (se) {
221	      const m = METRICS.find(function (x) { return x.id === se.id; });
222	      events.push({
223	        t: t0 - se.ago, id: m.id, name: m.name, unit: m.unit, kind: se.kind,
224	        from: se.from, to: se.to,
225	        msg: se.to === 'ok' ? '恢复正常' : (se.to === 'crit' ? '升至严重' : '进入警告')
226	      });
227	    });
228	    events.sort(function (a, b) { return b.t - a.t; });
229	  }
230	
231	  /* ---------- 1Hz 推进 ---------- */
232	  function tick(now) {
233	    METRICS.forEach(function (m) {
234	      const s = state[m.id];
235	      const tRel = (now - t0) / 1000;
236	      // 自然偶发异常（低概率）
237	      if (!s.incident && rand() < 0.0006) {
238	        s.incident = makeIncident(m, rand() < 0.5 ? 'spike' : 'drift', tRel);
239	      }
240	      let env = 0;
241	      if (s.incident) {
242	        env = envelope(s.incident, tRel);
243	        if (env === 0 && tRel > s.incident.start + s.incident.dur + s.incident.rel) s.incident = null;
244	      }
245	      const v = Math.max(0, rawValue(m, tRel, env));
246	      s.samples.push({ t: now, v: v });
247	      if (s.samples.length > WINDOW) s.samples.shift();
248	      advance(m, v, now);
249	    });
250	    lastTickAt = now;
251	  }
