253	  /* ---------- 人工注入（走同一条检测管线） ---------- */
254	  function inject() {
255	    const okList = METRICS.filter(function (m) { return state[m.id].status === 'ok' && !state[m.id].incident; });
256	    if (!okList.length) return null;
257	    const m = okList[Math.floor(rand() * okList.length)];
258	    const type = rand() < 0.5 ? 'spike' : 'drift';
259	    state[m.id].incident = makeIncident(m, type, (Date.now() - t0) / 1000);
260	    state[m.id].injectFlag = true;
261	    events.unshift({
262	      t: Date.now(), id: m.id, name: m.name, unit: m.unit, kind: 'inject',
263	      msg: '人工注入' + (type === 'spike' ? '突刺' : '漂移') + '（演示）'
264	    });
265	    if (events.length > 200) events.pop();
266	    return m.id;
267	  }
