269	  /* ---------- 初始化 ---------- */
270	  METRICS.forEach(function (m) {
271	    state[m.id] = {
272	      m: m, th: thresholdsOf(m), samples: [],
273	      status: null, sinceT: 0, okTicks: 0, incident: null, injectFlag: false
274	    };
275	  });
276	  seed();
277	  lastTickAt = Date.now();
