279	  /* ---------- 导出 ---------- */
280	  window.PulseStream = {
281	    METRICS: METRICS,
282	    DOM_LABELS: DOM_LABELS,
283	    DOM_ORDER: DOM_ORDER,
284	    WINDOW: WINDOW,
285	    state: state,
286	    events: events,
287	    fmt: fmt,
288	    classify: classify,
289	    tick: tick,
290	    inject: inject,
291	    t0: function () { return t0; },
292	    isRunning: function () { return running; },
293	    setRunning: function (r) { running = r; if (r) lastTickAt = Date.now(); },
294	    lastTickAt: function () { return lastTickAt; },
295	    transitions: function () { return transitions; }
296	  };
