1	/* ============================================================
2	 * PulseWall · app.js — 视图与交互（无框架、无依赖）
3	 * 渲染契约（SDIR）：
4	 *  - 网格结构仅首次构建，瓦片位置恒定不重排（fixed-grid-no-reflow）
5	 *  - 数值原位更新 + 短时高亮后静止（in-place-update）
6	 *  - 异常以色彩 + 异常条聚拢表达显著性（anomaly-strip）
7	 *  - 选中 → 检查器展示带时间戳证据链（trace-inspector）
8	 * ============================================================ */
9	(function () {
10	  'use strict';
11	  const S = window.PulseStream;
12	  const $ = function (id) { return document.getElementById(id); };
