25	  /* ---------- 瓦片构建（一次构建，永不重建结构） ---------- */
26	  function sparkSvg() {
27	    const ns = 'http://www.w3.org/2000/svg';
28	    const svg = document.createElementNS(ns, 'svg');
29	    svg.setAttribute('viewBox', '0 0 100 26');
30	    svg.setAttribute('preserveAspectRatio', 'none');
31	    svg.setAttribute('class', 'spark');
32	    svg.setAttribute('aria-hidden', 'true');
33	    const base = document.createElementNS(ns, 'line');
34	    base.setAttribute('class', 'sp-base');
35	    base.setAttribute('x1', '0'); base.setAttribute('x2', '100');
36	    const poly = document.createElementNS(ns, 'polyline');
37	    svg.appendChild(base); svg.appendChild(poly);
38	    return { svg: svg, poly: poly, base: base };
39	  }
