41	  function buildGrid() {
42	    const wall = $('region-metric-grid');
43	    const frag = document.createDocumentFragment();
44	    S.DOM_ORDER.forEach(function (dom) {
45	      const metrics = S.METRICS.filter(function (m) { return m.dom === dom; });
46	      const g = document.createElement('div');
