63	          '<span class="t-top"><span class="t-name">' + m.name + '</span><span class="t-dom">' + m.id + '</span></span>' +
64	          '<span class="t-mid"><span class="t-val">--</span><span class="t-unit">' + m.unit + '</span><span class="t-delta">—</span></span>';
65	        b.appendChild(sp.svg);
