77	  /* ---------- sparkline / 大图几何 ---------- */
78	  function pointsFor(m, w, h, pad) {
79	    const s = S.state[m.id];
80	    const vs = s.samples.map(function (p) { return p.v; });
81	    let lo = Math.min.apply(null, vs.concat([s.th.warn, s.th.crit, m.base]));
82	    let hi = Math.max.apply(null, vs.concat([s.th.warn, s.th.crit, m.base]));
83	    const span = (hi - lo) || Math.abs(m.base) * 0.1;
84	    lo -= span * 0.08; hi += span * 0.08;
85	    const n = vs.length;
86	    let pts = '';
87	    for (let i = 0; i < n; i++) {
88	      const x = (i / (S.WINDOW - 1)) * w;
89	      const y = pad + (1 - (vs[i] - lo) / (hi - lo)) * (h - pad * 2);
90	      pts += x.toFixed(2) + ',' + y.toFixed(2) + ' ';
91	    }
92	    return { pts: pts, lo: lo, hi: hi, n: n };
93	  }
94	
95	  function yOf(v, lo, hi, h, pad) { return pad + (1 - (v - lo) / (hi - lo)) * (h - pad * 2); }
96	
97	  function renderSpark(id) {
98	    const m = byId(id);
99	    const e = els[id];
100	    const g = pointsFor(m, 100, 26, 2);
101	    e.poly.setAttribute('points', g.pts);
102	    e.base.setAttribute('y1', yOf(m.base, g.lo, g.hi, 26, 2).toFixed(2));
103	    e.base.setAttribute('y2', e.base.getAttribute('y1'));
104	  }
