106	  /* ---------- 每秒原位更新 ---------- */
107	  function byId(id) { return S.METRICS.find(function (m) { return m.id === id; }); }
108	
109	  function fmtClock(t) {
110	    const d = new Date(t);
111	    const p = function (x) { return (x < 10 ? '0' : '') + x; };
112	    return p(d.getHours()) + ':' + p(d.getMinutes()) + ':' + p(d.getSeconds());
113	  }
114	
115	  function fmtDur(ms) {
116	    const s = Math.max(0, Math.floor(ms / 1000));
117	    return Math.floor(s / 60) + ':' + (s % 60 < 10 ? '0' : '') + (s % 60);
118	  }
