120	  function tickRender(now) {
121	    // 头部
122	    $('hdr-clock').textContent = fmtClock(now);
123	    let abn = 0;
124	    S.METRICS.forEach(function (m) { if (S.state[m.id].status !== 'ok') abn++; });
125	    $('hdr-stats').textContent = '异常 ' + abn + '/' + S.METRICS.length + ' · 转换 ' + S.transitions();
126	
127	    // 瓦片原位更新
128	    S.METRICS.forEach(function (m) {
129	      const e = els[m.id];
130	      const s = S.state[m.id];
131	      const cur = s.samples[s.samples.length - 1];
132	      const txt = S.fmt(m, cur.v);
133	      if (txt !== e.lastText) {
134	        e.val.textContent = txt;
135	        // 短高亮：只有超过噪声底的变化才标记（区分信号与噪声）
136	        const lb = lastBumpV[m.id];
137	        if (lb === undefined) { lastBumpV[m.id] = cur.v; }
138	        else if (Math.abs(cur.v - lb) >= m.base * 0.035) {
139	          e.val.classList.remove('bump');
140	          void e.val.offsetWidth;
141	          e.val.classList.add('bump');
142	          lastBumpV[m.id] = cur.v;
143	        }
144	        e.lastText = txt;
145	      }
146	      // Δ vs 60s 前
147	      const old = s.samples.length > 60 ? s.samples[s.samples.length - 61].v : s.samples[0].v;
148	      const pct = old !== 0 ? ((cur.v - old) / Math.abs(old)) * 100 : 0;
149	      const dtxt = (pct >= 0 ? '▲' : '▼') + Math.abs(pct).toFixed(1) + '%';
150	      if (dtxt !== e.lastDelta) {
151	        e.delta.textContent = dtxt;
152	        e.delta.className = 't-delta ' + (pct >= 0 ? 'up' : 'down');
153	        e.lastDelta = dtxt;
154	      }
155	      // 状态色：仅跃迁时改类
156	      const cls = 'tile st-' + s.status + (selectedId === m.id ? ' sel' : '');
157	      if (e.tile.className !== cls) {
158	        e.tile.className = cls;
159	        e.tile.setAttribute('aria-label', m.name + '，状态' + ({ ok: '正常', warn: '警告', crit: '严重', info: '恢复中' }[s.status]));
160	      }
161	      renderSpark(m.id);
162	    });
163	
164	    renderStrip(now);
165	    renderFeed();
166	    if (selectedId) updateInspectorLive(now);
167	  }
