275	  /* ---------- 检查器 ---------- */
276	  function historyRows(m) {
277	    const s = S.state[m.id];
278	    const rows = [];
279	    // 状态跃迁事件
280	    S.events.forEach(function (ev) {
281	      if (ev.id !== m.id) return;
282	      rows.push({ t: ev.t, v: ev.v, kind: ev.kind, note: ev.msg });
283	    });
284	    // 采样点（10s 粒度 + 最新）
285	    const samples = s.samples;
286	    for (let i = samples.length - 1; i >= 0; i -= 10) {
287	      const p = samples[i];
288	      if (!rows.some(function (r) { return Math.abs(r.t - p.t) < 500; })) {
289	        rows.push({ t: p.t, v: p.v, kind: null, note: '采样' });
290	      }
291	    }
292	    rows.sort(function (a, b) { return b.t - a.t; });
293	    return rows.slice(0, 40);
294	  }
