304	    const yb = yOf(m.base, g.lo, g.hi, H, pad);
305	    const warnBandTop = Math.min(yw, yc), warnBandH = Math.abs(yc - yw);
306	    let svg = '<svg viewBox="0 0 ' + W + ' ' + H + '" preserveAspectRatio="none" role="img" aria-label="走势图含阈值带">';
307	    svg += '<rect x="0" y="0" width="' + W + '" height="' + H + '" fill="rgba(255,255,255,0.02)"/>';
308	    svg += '<rect x="0" y="' + warnBandTop.toFixed(1) + '" width="' + W + '" height="' + warnBandH.toFixed(1) + '" fill="rgba(217,166,46,0.10)"/>';
309	    if (m.dir > 0) svg += '<rect x="0" y="' + yc.toFixed(1) + '" width="' + W + '" height="' + Math.max(0, H - yc).toFixed(1) + '" fill="rgba(244,81,91,0.12)"/>';
310	    else svg += '<rect x="0" y="0" width="' + W + '" height="' + Math.max(0, yc).toFixed(1) + '" fill="rgba(244,81,91,0.12)"/>';
311	    svg += '<line x1="0" x2="' + W + '" y1="' + yb.toFixed(1) + '" y2="' + yb.toFixed(1) + '" stroke="#2a3644" stroke-dasharray="3 4"/>';
312	    svg += '<line x1="0" x2="' + W + '" y1="' + yw.toFixed(1) + '" y2="' + yw.toFixed(1) + '" stroke="#d9a62e" stroke-dasharray="4 3" stroke-width="1"/>';
313	    svg += '<line x1="0" x2="' + W + '" y1="' + yc.toFixed(1) + '" y2="' + yc.toFixed(1) + '" stroke="#f4515b" stroke-dasharray="4 3" stroke-width="1"/>';
