1	import { readFile, stat } from "node:fs/promises";
2	import { join } from "node:path";
3	import { verifyEvidenceFile } from "prax-runtime";
4	import { captureContracts, captureImplementation, CONTRACT_FILES, type ExpectedMeasurementTarget } from "./measurement-binding.js";
5	import {
6	  ARTIFACT_CHECK_IDS,
7	  ARTIFACT_CHECK_DEFAULT_SEVERITY,
8	  CHECK_MEASUREMENT_MAP,
9	  MeasurementReceiptSchema,
10	  type ArtifactCheckId,
11	  type MeasurementReceipt,
12	  type MeasurementBindingStatus,
13	  type ValidationEvidence,
14	} from "./contracts.js";
15	
16	export interface ArtifactEvidenceInput {
17	  sessionDirectory: string;
18	  evidence: ValidationEvidence;
19	  expectedTarget?: ExpectedMeasurementTarget;
20	}
21	
22	export interface ArtifactEvidenceResult {
23	  status: "PASS" | "REVIEW" | "EXPAND" | "BLOCK";
24	  codes: string[];
25	  issues: string[];
26	  warnings: string[];
27	  /** check ids whose mapped measurement coverage failed (merge into evaluation missing_evidence) */
28	  missingEvidence: string[];
29	  /** receipt-backed → "measured"; everything else stays "attested" (spec §5.4) */
30	  provenanceByCheck: Map<string, "measured" | "attested">;
31	  /** valid, covering receipts seen (readiness receipt_ref uses the first) */
32	  receiptRefs: string[];
33	  /** open error-severity receipt failures (spec §5.7 R2) */
34	  errorFailuresOpen: number;
35	  /** catalog ids skipped in valid receipts (readiness claims.skipped) */
36	  skippedArtifactIds: string[];
37	  /** false when any receipt went stale (spec §5.7 R3) */
38	  evidenceCurrent: boolean;
39	  bindingByReceipt: Record<string, MeasurementBindingStatus>;
40	}
41	
42	const RECEIPT_PREFIX = "validation-evidence/";
43	
44	interface LoadedReceipt {
45	  ref: string;
46	  receipt: MeasurementReceipt | undefined;
47	  covering: boolean; // false when stale (spec §5.7 R3) or invalid
48	}
49	
50	function invertMap(): Map<ArtifactCheckId, string[]> {
51	  const inverted = new Map<ArtifactCheckId, string[]>();
52	  for (const [checkId, artifactIds] of Object.entries(CHECK_MEASUREMENT_MAP)) {
53	    for (const artifactId of artifactIds) {
54	      const owners = inverted.get(artifactId) ?? [];
55	      owners.push(checkId);
56	      inverted.set(artifactId, owners);
57	    }
58	  }
59	  return inverted;
60	}
61	
62	async function artifactMtime(sessionDirectory: string, fileName: string): Promise<Date | undefined> {
63	  try {
64	    const stats = await stat(join(sessionDirectory, fileName));
65	    return stats.mtime;
66	  } catch {
67	    return undefined;
68	  }
69	}
70	
71	/**
72	 * Receipt verification and cross-check (spec §5.4). For every evidence item:
73	 * declared receipts are file-verified (containment under
74	 * validation-evidence/), schema-parsed, digest-bound (sha256 recomputed from
75	 * disk — declared values are never trusted), staleness-checked against the
76	 * gated artifacts (§5.7 R3), and cross-checked against claimed outcomes. A
77	 * receipt `fail` contradicting a claimed `pass` BLOCKs; mapped checks passing
78	 * without receipt coverage EXPAND; skipped-with-reason satisfies coverage
79	 * honestly but stays `attested`.
80	 */
81	export async function verifyArtifactEvidence(input: ArtifactEvidenceInput): Promise<ArtifactEvidenceResult> {
82	  const codes: string[] = [];
83	  const issues: string[] = [];
84	  const warnings: string[] = [];
85	  const missingEvidence: string[] = [];
86	  const provenanceByCheck = new Map<string, "measured" | "attested">();
87	  const bindingByReceipt: Record<string, MeasurementBindingStatus> = {};
88	  let evidenceCurrent = true;
89	
90	  const addIssue = (code: string, issue: string) => {
91	    if (!codes.includes(code)) codes.push(code);
92	    issues.push(`${code}: ${issue}`);
93	  };
94	
95	  const sdirMtime = await artifactMtime(input.sessionDirectory, "screen.sdir.yaml");
96	  const briefMtime = await artifactMtime(input.sessionDirectory, "implementation-brief.yaml");
97	  const newestArtifact = [sdirMtime, briefMtime].reduce<Date | undefined>(
98	    (newest, current) => (current !== undefined && (newest === undefined || current > newest) ? current : newest),
99	    undefined,
100	  );
101	
102	  // ── load and verify every declared receipt ──
103	  const loaded = new Map<string, LoadedReceipt>();
104	  for (const item of input.evidence.items) {
105	    if (item.measurement_receipt === undefined) continue;
106	    const ref = item.measurement_receipt;
107	    if (loaded.has(ref)) continue;
108	
109	    const verified = await verifyEvidenceFile(input.sessionDirectory, ref, RECEIPT_PREFIX);
110	    if (!verified.ok) {
111	      addIssue("EVIDENCE_FILE_INVALID", verified.error);
112	      loaded.set(ref, { ref, receipt: undefined, covering: false });
113	      bindingByReceipt[ref] = "invalid";
114	      evidenceCurrent = false;
115	      continue;
116	    }
117	    let parsed: MeasurementReceipt | undefined;
118	    try {
119	      parsed = MeasurementReceiptSchema.parse(JSON.parse(await readFile(join(input.sessionDirectory, ref), "utf8")));
120	    } catch (error) {
121	      addIssue("MEASUREMENT_RECEIPT_INVALID", `${ref} does not parse as a measurement receipt: ${error instanceof Error ? error.message : String(error)}`);
122	      loaded.set(ref, { ref, receipt: undefined, covering: false });
123	      bindingByReceipt[ref] = "invalid";
124	      evidenceCurrent = false;
125	      continue;
126	    }
127	
128	    let covering = true;
129	    bindingByReceipt[ref] = parsed.receipt_version === "0.1" ? "legacy_unbound" : "unverified_target";
130	    if (parsed.receipt_version === "0.1" && input.expectedTarget !== undefined) {
131	      addIssue("MEASUREMENT_BINDING_REQUIRED", `receipt ${ref} predates implementation binding but this session has a prepared measurement target`);
132	      covering = false;
133	    }
134	    // digest binding: recompute every declared evidence hash from disk
135	    for (const check of parsed.checks) {
136	      for (const evidenceRef of check.evidence_refs) {
137	        const evidenceVerified = await verifyEvidenceFile(input.sessionDirectory, evidenceRef.ref, RECEIPT_PREFIX);
138	        if (!evidenceVerified.ok) {
139	          addIssue("EVIDENCE_FILE_INVALID", `receipt ${ref} declares unreadable evidence: ${evidenceVerified.error}`);
140	          covering = false;
141	          continue;
142	        }
143	        if (evidenceVerified.sha256 !== evidenceRef.sha256) {
144	          addIssue("EVIDENCE_DIGEST_MISMATCH", `receipt ${ref} declares sha256 ${evidenceRef.sha256.slice(0, 12)}… for ${evidenceRef.ref} but the file hashes to ${evidenceVerified.sha256.slice(0, 12)}…`);
145	          covering = false;
146	        }
147	      }
148	    }
149	
150	    // staleness (§5.7 R3): a receipt older than the newest gated artifact
151	    // does not count as coverage — human edits invalidate prior measurement
152	    if (parsed.receipt_version === "0.1" && newestArtifact !== undefined && new Date(parsed.run_at) < newestArtifact) {
153	      addIssue("MEASUREMENT_RECEIPT_STALE", `receipt ${ref} ran at ${parsed.run_at}, before the newest gated artifact change (${newestArtifact.toISOString()}) — measurement is stale and does not cover`);
154	      covering = false;
155	    }
156	    if (parsed.receipt_version === "0.2") {
157	      if (parsed.checks.some((check) => check.status === "skipped" && ARTIFACT_CHECK_DEFAULT_SEVERITY[check.id] === "error")) {
158	        addIssue("MEASUREMENT_INCOMPLETE", `receipt ${ref} did not complete every error-tier measurement; self-attestation cannot close the missing measurement`);
159	      }
160	      if (parsed.target_validation.status === "invalid") {
161	        addIssue("MEASUREMENT_TARGET_INVALID", `receipt ${ref} has an invalid target: ${parsed.target_validation.issues.join("; ")}`);
162	        covering = false;
163	      }
164	      if (input.expectedTarget === undefined) {
165	        addIssue("MEASUREMENT_TARGET_UNVERIFIED", `receipt ${ref} has no independently prepared target; its declared root is not read or verified`);
166	        evidenceCurrent = false;
167	      } else {
168	        try {
169	          const expected = input.expectedTarget;
170	          const implementation = await captureImplementation(expected.appRoot);
171	          const binding = parsed.binding;
172	          if (binding.implementation.root !== implementation.root || parsed.target.app_root !== implementation.root
173	            || binding.entry !== expected.entry || binding.scenario !== expected.scenario || binding.session_id !== expected.sessionId) {
174	            throw new Error("receipt root, entry, scenario or session does not match the prepared target");
175	          }
176	          if (binding.implementation.digest !== implementation.digest) throw new Error("implementation content changed since measurement");
177	          const contracts = await captureContracts(input.sessionDirectory);
178	          if (CONTRACT_FILES.some((name) => binding.contract_digests[name] !== contracts[name])) throw new Error("design contract content changed since measurement");
179	          bindingByReceipt[ref] = binding.implementation.kind === "static_tree" ? "implementation_current" : "association_current";
180	        } catch (error) {
181	          addIssue("MEASUREMENT_BINDING_INVALID", `receipt ${ref}: ${error instanceof Error ? error.message : String(error)}`);
182	          covering = false;
183	        }
184	      }
185	    }
186	    if (!covering) {
187	      bindingByReceipt[ref] = "invalid";
188	      evidenceCurrent = false;
189	    }
190	
191	    // skipped spread: >50% of the catalog skipped demands human environment confirmation
192	    const skippedCount = parsed.checks.filter((check) => check.status === "skipped").length;
193	    if (skippedCount / ARTIFACT_CHECK_IDS.length > 0.5) {
194	      warnings.push(`measurement environment suspect: ${skippedCount}/${ARTIFACT_CHECK_IDS.length} catalog checks skipped in ${ref} — confirm the measurement environment with a human before trusting this receipt`);
195	    }
196	
197	    loaded.set(ref, { ref, receipt: parsed, covering });
198	  }
199	
200	  // ── contradiction cross-check (receipt fail vs claimed pass) ──
201	  const inverted = invertMap();
202	  for (const entry of loaded.values()) {
203	    if (entry.receipt === undefined) continue;
204	    for (const check of entry.receipt.checks) {
205	      if (check.status !== "fail") continue;
206	      for (const ownerId of inverted.get(check.id) ?? []) {
207	        const claimed = input.evidence.items.find((item) => item.check_id === ownerId && item.outcome === "pass");
208	        if (claimed !== undefined) {
209	          addIssue("VALIDATION_MEASUREMENT_CONTRADICTION", `receipt ${entry.ref} measures ${check.id} as fail while check '${ownerId}' claims pass — measured evidence outranks attestation (PRAX-P-043)`);
210	        }
211	      }
212	    }
213	  }
214	
215	  // ── coverage enforcement + provenance ──
216	  for (const item of input.evidence.items) {
217	    const mapped = CHECK_MEASUREMENT_MAP[item.check_id];
218	    if (mapped === undefined || mapped.length === 0 || item.outcome !== "pass") continue;
219	
220	    const receipts = (item.measurement_receipt === undefined ? [] : [item.measurement_receipt])
221	      .map((ref) => loaded.get(ref))
222	      .filter((entry): entry is LoadedReceipt => entry !== undefined && entry.covering && entry.receipt !== undefined);
223	
224	    const statusById = new Map<ArtifactCheckId, "pass" | "fail" | "skipped">();
225	    for (const entry of receipts) {
226	      for (const check of entry.receipt!.checks) {
227	        if (mapped.includes(check.id) && !statusById.has(check.id)) {
228	          statusById.set(check.id, check.status);
229	        }
230	      }
231	    }
232	
233	    const uncovered = mapped.filter((artifactId) => !statusById.has(artifactId));
234	    if (uncovered.length > 0) {
235	      addIssue("MEASUREMENT_RECEIPT_MISSING", `check '${item.check_id}' claims pass but no valid receipt covers ${uncovered.join(", ")}`);
236	      if (!missingEvidence.includes(item.check_id)) missingEvidence.push(item.check_id);
237	      provenanceByCheck.set(item.check_id, "attested");
238	      continue;
239	    }
240	
241	    const skippedIds = mapped.filter((artifactId) => statusById.get(artifactId) === "skipped");
242	    if (skippedIds.length > 0) {
243	      provenanceByCheck.set(item.check_id, "attested");
244	      warnings.push(`check '${item.check_id}' stays attested: measurement unavailable for ${skippedIds.join(", ")} (skipped is not passed) — self-attestation honestly downgraded`);
245	    } else {
246	      provenanceByCheck.set(item.check_id, "measured");
247	    }
248	  }
249	
250	  const block = codes.includes("MEASUREMENT_RECEIPT_INVALID")
251	    || codes.includes("MEASUREMENT_BINDING_REQUIRED")
252	    || codes.includes("MEASUREMENT_TARGET_INVALID")
253	    || codes.includes("MEASUREMENT_BINDING_INVALID")
254	    || codes.includes("EVIDENCE_DIGEST_MISMATCH")
255	    || codes.includes("VALIDATION_MEASUREMENT_CONTRADICTION");
256	  const review = codes.includes("MEASUREMENT_TARGET_UNVERIFIED") || codes.includes("MEASUREMENT_INCOMPLETE") || warnings.some((warning) => warning.includes("measurement environment suspect"));
257	  const status: ArtifactEvidenceResult["status"] = block
258	    ? "BLOCK"
259	    : review
260	      ? "REVIEW"
261	      : codes.length > 0 || missingEvidence.length > 0
262	        ? "EXPAND"
263	        : "PASS";
264	
265	  const validReceipts = [...loaded.values()].filter((entry) => entry.covering && entry.receipt !== undefined);
266	  return {
267	    status,
268	    codes,
269	    issues,
270	    warnings,
271	    missingEvidence,
272	    provenanceByCheck,
273	    receiptRefs: validReceipts.map((entry) => entry.ref),
274	    errorFailuresOpen: validReceipts.reduce(
275	      (count, entry) =>
276	        count + entry.receipt!.checks.filter((check) => check.severity === "error" && check.status === "fail").length,
277	      0,
278	    ),
279	    skippedArtifactIds: [...new Set(validReceipts.flatMap((entry) => entry.receipt!.checks.filter((check) => check.status === "skipped").map((check) => check.id)))],
280	    evidenceCurrent,
281	    bindingByReceipt,
282	  };
283	}
